 masks={'red':(r>190)&(r>g+35)&(r>b+20),'blue':(b>r+25)&(b>g+5)&(g>100),'white':(r>240)&(g>235)&(b>230),'lav':(r>195)&(b>220)&(b>r+12)&(g<r-5)}
